  "sentences": [
    {
      "id": 1,
      "text": "Revolving credit utilization is the most important driver of default risk, with a strong effect that increases as the share of the credit limit in use rises."
    },
    {
      "id": 2,
      "text": "The number of past delinquencies is the second or third most important driver, showing a moderate effect where risk increases with the count of delinquencies."
    },
    {
      "id": 3,
      "text": "Annual income ranks second to fifth in importance, having a weak to moderate effect where risk decreases as income grows."
    },
    {
      "id": 4,
      "text": "The length of the credit history ranks third to eighth, with a weak to moderate effect where risk decreases as the history lengthens."
    },
    {
      "id": 5,
      "text": "Age, debt-to-income ratio, months at current address, number of dependents, and recent credit inquiries hardly matter to the model's predictions."
    },
    {
      "id": 6,
      "text": "The effect of revolving credit utilization on risk is amplified when the number of past delinquencies is high, which is the most significant interaction in the model."
    }
  ]
}

